import{H as e,V as t,et as n,j as r}from"./chunks/framework.ChZHrXbO.js";import{ds as i,fs as a,gs as o,hs as s,ls as c,ms as l,ps as u,us as d}from"./chunks/assets.BxHYjuf8.js";var f=JSON.parse(`{"title":"索引","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/indexes.md","filePath":"mysql/indexes.md"}`),p={name:`mysql/indexes.md`};function m(r,f,p,m,h,g){return n(),t(`div`,null,[...f[0]||=[e(`<h1 id="索引" tabindex="-1">索引 <a class="header-anchor" href="#索引" aria-label="Permalink to “索引”">​</a></h1><h2 id="_1-概述" tabindex="-1">1.概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to “1.概述”">​</a></h2><p>索引是帮助 MySQL <strong>高效获取数据</strong>的<strong>数据结构（有序）</strong>。在数据之外，数据库系统还维护着满足特定查找算法的数据结构，这些数据结构以某种方式引用（指向）数据，这样就可以在这些数据结构上实现高级查询算法，这种数据结构就是索引。</p><p><strong>优点</strong>：</p><ul><li><p>提高数据检索效率，降低数据库的IO成本</p></li><li><p>通过索引列对数据进行排序，降低数据排序的成本，降低CPU的消耗</p></li></ul><p><strong>缺点</strong>：</p><ul><li><p>索引列也是要占用空间的</p></li><li><p>索引大大提高了查询效率，但降低了更新的速度，比如 INSERT、UPDATE、DELETE</p></li></ul><h2 id="_2-索引结构" tabindex="-1">2.索引结构 <a class="header-anchor" href="#_2-索引结构" aria-label="Permalink to “2.索引结构”">​</a></h2><table tabindex="0"><thead><tr><th>索引结构</th><th>描述</th></tr></thead><tbody><tr><td><strong>B+Tree</strong></td><td>最常见的索引类型，大部分引擎都支持B+树索引</td></tr><tr><td>Hash</td><td>底层数据结构是用哈希表实现，只有精确匹配索引列的查询才有效，不支持范围查询</td></tr><tr><td>R-Tree(空间索引)</td><td>空间索引是 MyISAM 引擎的一个特殊索引类型，主要用于地理空间数据类型，通常使用较少</td></tr><tr><td>Full-Text(全文索引)</td><td>是一种通过建立倒排索引，快速匹配文档的方式，类似于 Lucene, Solr, ES</td></tr></tbody></table><table tabindex="0"><thead><tr><th>索引</th><th>InnoDB</th><th>MyISAM</th><th>Memory</th></tr></thead><tbody><tr><td>B+Tree索引</td><td>支持</td><td>支持</td><td>支持</td></tr><tr><td>Hash索引</td><td>不支持</td><td>不支持</td><td>支持</td></tr><tr><td>R-Tree索引</td><td>不支持</td><td>支持</td><td>不支持</td></tr><tr><td>Full-text</td><td>5.6版本后支持</td><td>支持</td><td>不支持</td></tr></tbody></table><h3 id="_2-1-b-tree" tabindex="-1">2.1 B+Tree <a class="header-anchor" href="#_2-1-b-tree" aria-label="Permalink to “2.1 B+Tree”">​</a></h3><p><img src="`+o+`" alt="997786dfbf2c47c484082a3d48bc3c65png" width="1566" height="782"></p><p>二叉树的缺点可以用红黑树来解决：</p><p><img src="`+s+`" alt="fe864cd19bd64e76a0db00cf9b3cbaacpng" width="1581" height="1022"></p><p>红黑树也存在大数据量情况下，层级较深，检索速度慢的问题。</p><h3 id="_2-2-b-tree-多路平衡查找树" tabindex="-1">2.2 B-Tree（多路平衡查找树） <a class="header-anchor" href="#_2-2-b-tree-多路平衡查找树" aria-label="Permalink to “2.2 B-Tree（多路平衡查找树）”">​</a></h3><p>以一棵最大度数（max-degree，指一个节点的子节点个数）为5（5阶）的 b-tree 为例（每个节点最多存储4个key，5个指针）：</p><p><img src="`+l+`" alt="11ed8574fe144d21906bc77e3918e7fapng" width="1545" height="475"></p><ul><li>每一个节点都存储数据</li></ul><p>演示网站：</p><p><a href="https://www.cs.usfca.edu/~galles/visualization/BTree.html" target="_blank" rel="noreferrer">https://www.cs.usfca.edu/~galles/visualization/BTree.html</a></p><h3 id="_2-3-b-tree" tabindex="-1">2.3 B+Tree <a class="header-anchor" href="#_2-3-b-tree" aria-label="Permalink to “2.3 B+Tree”">​</a></h3><p><img src="`+u+`" alt="83ad4f150a2b40d79fcc8e78fea00759png" width="1565" height="488"></p><ul><li><p>所有的数据都会出现在叶子节点</p></li><li><p>叶子节点形成一个单向链表</p></li></ul><p>演示网站：</p><p><a href="https://www.cs.usfca.edu/~galles/visualization/BPlusTree.html" target="_blank" rel="noreferrer">https://www.cs.usfca.edu/~galles/visualization/BPlusTree.html</a></p><p>MySQL 索引数据结构对经典的 B+Tree 进行了优化。在原 B+Tree 的基础上，增加一个指向相邻叶子节点的链表指针，就形成了带有顺序指针的 B+Tree，提高区间访问的性能：</p><p><img src="`+a+`" alt="5167a8266fae4e04bf40c3a9963b0439png" width="1523" height="491"></p><h3 id="_2-4-hash" tabindex="-1">2.4 Hash <a class="header-anchor" href="#_2-4-hash" aria-label="Permalink to “2.4 Hash”">​</a></h3><p>哈希索引就是采用一定的hash算法，将键值换算成新的hash值，映射到对应的槽位上，然后存储在hash表中。</p><ul><li>如果两个（或多个）键值，映射到一个相同的槽位上，他们就产生了hash冲突（也称为hash碰撞），可以通过链表来解决</li></ul><p><img src="`+i+`" alt="d8a6b41b8a0f45e08274c63a6cce5deapng" width="2395" height="846"></p><p><strong>特点</strong>：</p><ul><li><p>Hash索引只能用于对等比较（=、in），不支持范围查询（between、&gt;、&lt;、…）</p></li><li><p>无法利用索引完成排序操作</p></li><li><p>查询效率高，通常只需要一次检索就可以了，效率通常要高于 B+Tree 索引</p></li></ul><p><strong>存储引擎支持</strong>：</p><p>在MySQL中，支持hash索引的是Memory引擎，而InnoDB中具有自适应hash功能，hash索引是存储引擎根据 B+Tree 索引在指定条件下自动构建的。</p><h3 id="_2-5-思考" tabindex="-1">2.5 思考 <a class="header-anchor" href="#_2-5-思考" aria-label="Permalink to “2.5 思考”">​</a></h3><p>为什么 InnoDB 存储引擎选择使用 B+Tree 索引结构？</p><ol><li><p>相对于二叉树，层级更少，搜索效率高</p></li><li><p>对于 B-Tree，无论是叶子节点还是非叶子节点，都会保存数据，这样导致一页中存储的键值减少，指针也跟着减少，要同样保存大量数据，只能增加树的高度，导致性能降低</p></li><li><p>相对于 Hash 索引，B+Tree 支持范围匹配及排序操作</p></li></ol><h2 id="_3-索引分类" tabindex="-1">3.索引分类 <a class="header-anchor" href="#_3-索引分类" aria-label="Permalink to “3.索引分类”">​</a></h2><h3 id="_3-1-分类" tabindex="-1">3.1 分类 <a class="header-anchor" href="#_3-1-分类" aria-label="Permalink to “3.1 分类”">​</a></h3><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>特点</th><th>关键字</th></tr></thead><tbody><tr><td>主键索引</td><td>针对于表中主键创建的索引</td><td>默认自动创建，只能有一个</td><td>PRIMARY</td></tr><tr><td>唯一索引</td><td>避免同一个表中某数据列中的值重复</td><td>可以有多个</td><td>UNIQUE</td></tr><tr><td>常规索引</td><td>快速定位特定数据</td><td>可以有多个</td><td></td></tr><tr><td>全文索引</td><td>全文索引查找的是文本中的关键词，而不是比较索引中的值</td><td>可以有多个</td><td>FULLTEXT</td></tr></tbody></table><p>在 InnoDB 存储引擎中，根据索引的存储形式，又可以分为以下两种：</p><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>特点</th></tr></thead><tbody><tr><td>聚集索引(Clustered Index)</td><td>将数据存储与索引放一块，索引结构的叶子节点保存了行数据</td><td>必须有，而且只有一个</td></tr><tr><td>二级索引(Secondary Index)</td><td>将数据与索引分开存储，索引结构的叶子节点关联的是对应的主键</td><td>可以存在多个</td></tr></tbody></table><h3 id="_3-2-演示图" tabindex="-1">3.2 演示图 <a class="header-anchor" href="#_3-2-演示图" aria-label="Permalink to “3.2 演示图”">​</a></h3><p><img src="`+d+`" alt="9101e3c07484407b8ad262d11f2705b9png" width="1552" height="791"></p><p><img src="`+c+`" alt="5746243eaca74fb2adce97df069ad964png" width="1648" height="811"></p><h3 id="_3-3-聚集索引选取规则" tabindex="-1">3.3 聚集索引选取规则 <a class="header-anchor" href="#_3-3-聚集索引选取规则" aria-label="Permalink to “3.3 聚集索引选取规则”">​</a></h3><ul><li><p>如果存在主键，主键索引就是聚集索引</p></li><li><p>如果不存在主键，将使用第一个唯一(UNIQUE)索引作为聚集索引</p></li><li><p>如果表没有主键或没有合适的唯一索引，则 InnoDB 会自动生成一个 rowid 作为隐藏的聚集索引</p></li></ul><h3 id="_3-4-思考" tabindex="-1">3.4 思考 <a class="header-anchor" href="#_3-4-思考" aria-label="Permalink to “3.4 思考”">​</a></h3><p>（1）以下 SQL 语句，哪个执行效率高？为什么？</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> name</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Arm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">-- 备注：id为主键，name字段创建的有索引</span></span></code></pre></div><p>答：第一条语句，因为第二条需要回表查询，相当于两个步骤。</p><p>（2）InnoDB 主键索引的 B+Tree 高度为多少？</p><p>答：假设一行数据大小为1k，一页中可以存储16行这样的数据。InnoDB 的指针占用6个字节的空间，主键假设为bigint，占用字节数为8. 可得公式：<code>n * 8 + (n + 1) * 6 = 16 * 1024</code>，其中 8 表示 bigint 占用的字节数，n 表示当前节点存储的key的数量，(n + 1) 表示指针数量（比key多一个）。算出n约为1170。</p><p>如果树的高度为2，那么他能存储的数据量大概为：<code>1171 * 16 = 18736</code>； 如果树的高度为3，那么他能存储的数据量大概为：<code>1171 * 1171 * 16 = 21939856</code>。</p><p>另外，如果有成千上万的数据，那么就要考虑分表。</p><h2 id="_4-语法" tabindex="-1">4.语法 <a class="header-anchor" href="#_4-语法" aria-label="Permalink to “4.语法”">​</a></h2><p>创建索引</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ UNIQUE | FULLTEXT ] </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">INDEX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index_name </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_name (index_col_name, ...);</span></span></code></pre></div><ul><li>如果不加 CREATE 后面索引类型参数，则创建的是常规索引</li></ul><p>查看索引</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SHOW </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">INDEX</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_name;</span></span></code></pre></div><p>删除索引</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> INDEX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> index_name </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> table_name;</span></span></code></pre></div><h2 id="_5-索引使用规则" tabindex="-1">5.索引使用规则 <a class="header-anchor" href="#_5-索引使用规则" aria-label="Permalink to “5.索引使用规则”">​</a></h2><h3 id="_5-1-最左前缀法则" tabindex="-1">5.1 最左前缀法则 <a class="header-anchor" href="#_5-1-最左前缀法则" aria-label="Permalink to “5.1 最左前缀法则”">​</a></h3><p>如果索引关联了多列（联合索引），要遵守最左前缀法则，最左前缀法则指的是查询从索引的最左列开始，并且不跳过索引中的列。</p><p>如果跳跃某一列，索引将部分失效（后面的字段索引失效）。</p><ul><li>比较特殊的一种情况是如果直接跳跃第一列，那么第一列后面的索引都会失效，即此时联合索引完全失效</li></ul><p>联合索引中，出现范围查询（&lt;, &gt;），范围查询右侧的列索引失效。可以用&gt;=或者&lt;=来规避索引失效问题。</p><ul><li>字段的位置可以任意，只要缺少复合索引某个字段，后面的字段索引全部失效</li></ul><h3 id="_5-2-索引失效情况" tabindex="-1">5.2 索引失效情况 <a class="header-anchor" href="#_5-2-索引失效情况" aria-label="Permalink to “5.2 索引失效情况”">​</a></h3><ol><li><p>在索引列上进行运算操作，索引将失效。如：<code>explain select * from tb_user where substring(phone, 10, 2) = &#39;15&#39;;</code></p></li><li><p>字符串类型字段使用时，不加引号，索引将失效。如：<code>explain select * from tb_user where phone = 17799990015;</code>，此处phone的值没有加引号</p></li><li><p>模糊查询中，如果仅仅是尾部模糊匹配，索引不会失效；如果是头部模糊匹配，索引失效。如：<code>explain select * from tb_user where profession like &#39;%工程&#39;;</code>，前后都有 % 也会失效</p></li><li><p>用 or 分割开的条件，如果 or 其中一个条件的列没有索引，那么涉及的索引都不会被用到</p></li><li><p>如果 MySQL 评估使用索引比全表更慢，则不使用索引</p></li></ol><h3 id="_5-3-sql-提示" tabindex="-1">5.3 SQL 提示 <a class="header-anchor" href="#_5-3-sql-提示" aria-label="Permalink to “5.3 SQL 提示”">​</a></h3><p>是优化数据库的一个重要手段，简单来说，就是在SQL语句中加入一些人为的提示来达到优化操作的目的。</p><p>使用索引：</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">use</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(索引名) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 查询条件;</span></span></code></pre></div><p>不使用哪个索引：</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">ignore</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(索引名) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 查询条件;</span></span></code></pre></div><p>必须使用哪个索引：</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名 </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">force</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> index</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(索引名) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">where</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 查询条件;</span></span></code></pre></div><ul><li>use 是建议，不一定使用，实际使用哪个索引 MySQL 还会自己权衡运行速度去更改，force就是无论如何都强制使用该索引。</li></ul><h3 id="_5-4-覆盖索引" tabindex="-1">5.4 覆盖索引 <a class="header-anchor" href="#_5-4-覆盖索引" aria-label="Permalink to “5.4 覆盖索引”">​</a></h3><p>即查询使用了索引，并且需要返回的列，在该索引中已经全部能找到</p><p>尽量使用覆盖索引，减少select *的书写</p><h4 id="_5-4-1-explain-中-extra-字段含义" tabindex="-1">5.4.1 explain 中 extra 字段含义 <a class="header-anchor" href="#_5-4-1-explain-中-extra-字段含义" aria-label="Permalink to “5.4.1 explain 中 extra 字段含义”">​</a></h4><ol><li><p><code>using index condition</code>：查找使用了索引，但是需要回表查询数据</p></li><li><p><code>using where; using index;</code>：查找使用了索引，但是需要的数据都在索引列中能找到，所以不需要回表查询</p></li></ol><p>如果在聚集索引中直接能找到对应的行，则直接返回行数据，只需要一次查询，哪怕是select *；如果在辅助索引中找聚集索引，如<code>select id, name from xxx where name=&#39;xxx&#39;;</code>，也只需要通过辅助索引(name)查找到对应的id，返回name和name索引对应的id即可，只需要一次查询；如果是通过辅助索引查找其他字段，则需要回表查询，如<code>select id, name, gender from xxx where name=&#39;xxx&#39;;</code></p><p>所以尽量不要用<code>select *</code>，容易出现回表查询，降低效率，除非有联合索引包含了所有字段</p><h4 id="_5-4-2-面试题" tabindex="-1">5.4.2 面试题 <a class="header-anchor" href="#_5-4-2-面试题" aria-label="Permalink to “5.4.2 面试题”">​</a></h4><p>一张表，有四个字段（id, username, password, status），由于数据量大，需要对以下SQL语句进行优化，该如何进行才是最优方案： <code>select id, username, password from tb_user where username=&#39;itcast&#39;;</code></p><p>解：给username和password字段建立联合索引，则不需要回表查询，直接覆盖索引</p><h3 id="_5-5-前缀索引" tabindex="-1">5.5 前缀索引 <a class="header-anchor" href="#_5-5-前缀索引" aria-label="Permalink to “5.5 前缀索引”">​</a></h3><p>当字段类型为字符串（varchar, text等）时，有时候需要索引很长的字符串，这会让索引变得很大，查询时，浪费大量的磁盘IO，影响查询效率，此时可以只降字符串的一部分前缀，建立索引，这样可以大大节约索引空间，从而提高索引效率</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">create</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> index</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 索引名</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名(列名(n));</span></span></code></pre></div><p>前缀长度：可以根据索引的选择性来决定，而选择性是指不重复的索引值（基数）和数据表的记录总数的比值，索引选择性越高则查询效率越高，唯一索引的选择性是1，这是最好的索引选择性，性能也是最好的。</p><p>求选择性公式（截取长度可以任取，不断运行，直到合适为止）：</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">distinct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 列名) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">select</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">distinct</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> substring</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(列名, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, 截取长度)) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 表名;</span></span></code></pre></div><ul><li>show index 里面的sub_part可以看到接取的长度</li></ul><h3 id="_5-6-不满足最左前缀法则仍可能触发复合索引的情况" tabindex="-1">5.6 不满足最左前缀法则仍可能触发复合索引的情况 <a class="header-anchor" href="#_5-6-不满足最左前缀法则仍可能触发复合索引的情况" aria-label="Permalink to “5.6 不满足最左前缀法则仍可能触发复合索引的情况”">​</a></h3><p>只是可能触发，优化器可能仍选择全表扫描。</p><h4 id="_5-6-1-覆盖索引" tabindex="-1">5.6.1 覆盖索引 <a class="header-anchor" href="#_5-6-1-覆盖索引" aria-label="Permalink to “5.6.1 覆盖索引”">​</a></h4><p>当查询的字段完全包含在联合索引中，即使 <code>WHERE</code> 条件不满足最左前缀，MySQL 可能选择 全索引扫描（而非全表扫描）来直接返回数据例如：</p><p>索引（a,b,c），<code>SELECT b, c FROM table WHERE b = 10;</code>，数据可直接从索引中提取（无需回表），优化器可能选择扫描整个索引。</p><h4 id="_5-6-2-索引下推-icp" tabindex="-1">5.6.2 索引下推（ICP） <a class="header-anchor" href="#_5-6-2-索引下推-icp" aria-label="Permalink to “5.6.2 索引下推（ICP）”">​</a></h4><p>MySQL 5.6+ 支持 ICP，当查询条件包含部分联合索引列时，即使不满足最左前缀，存储引擎层仍会利用索引过滤数据，减少回表次数，例如：</p><p>索引（a,b,c），<code>SELECT * FROM table WHERE a = 1 AND c = 3;</code>，a 作为最左前缀生效，c 的条件通过 ICP 在存储引擎层过滤。</p><ul><li>索引下推（ICP）需在 MySQL 5.6+ 且开启 <code>optimizer_switch=index_condition_pushdown=on</code></li></ul><h4 id="_5-6-3-排序-索引优化" tabindex="-1">5.6.3 排序/索引优化 <a class="header-anchor" href="#_5-6-3-排序-索引优化" aria-label="Permalink to “5.6.3 排序/索引优化”">​</a></h4><p>若 ORDER BY 或 GROUP BY 的字段顺序与联合索引一致，即使 WHERE 条件不满足最左前缀，仍可能利用索引优化排序或分组，例如：</p><p>索引（a,b），<code>SELECT * FROM table WHERE a &gt; 1 ORDER BY b;</code>，索引 (a, b) 天然按 a, b 排序，优化器可能选择索引避免 filesort。</p><h4 id="_5-6-4-范围查询后的等值查询" tabindex="-1">5.6.4 范围查询后的等值查询 <a class="header-anchor" href="#_5-6-4-范围查询后的等值查询" aria-label="Permalink to “5.6.4 范围查询后的等值查询”">​</a></h4><p>若查询条件中 最左前缀为范围查询，后续列的等值条件可能仍会使用索引，例如：</p><p>索引（a,b,c），<code>SELECT * FROM table WHERE a &gt; 1 AND b = 2;</code>，索引会先按 a 的范围查找，再匹配 b 的等值条件（需结合索引下推）。</p><h3 id="_5-7-单列索引和联合索引" tabindex="-1">5.7 单列索引和联合索引 <a class="header-anchor" href="#_5-7-单列索引和联合索引" aria-label="Permalink to “5.7 单列索引和联合索引”">​</a></h3><p>单列索引：即一个索引只包含单个列</p><p>联合索引：即一个索引包含了多个列</p><p>在业务场景中，如果存在多个查询条件，考虑针对于查询字段建立索引时，<strong>建议建立联合索引</strong>，而非单列索引</p><ul><li>多条件联合查询时，MySQL优化器会评估哪个字段的索引效率更高，会选择该索引完成本次查询</li></ul><h3 id="_5-8-设计原则" tabindex="-1">5.8 设计原则 <a class="header-anchor" href="#_5-8-设计原则" aria-label="Permalink to “5.8 设计原则”">​</a></h3><ol><li><p>针对于数据量较大，且查询比较频繁的表建立索引</p></li><li><p>针对于常作为查询条件（where）、排序（order by）、分组（group by）操作的字段建立索引</p></li><li><p>尽量选择区分度高的列作为索引，尽量建立唯一索引，区分度越高，使用索引的效率越高</p></li><li><p>如果是字符串类型的字段，字段长度较长，可以针对于字段的特点，建立前缀索引</p></li><li><p>尽量使用联合索引，减少单列索引，查询时，联合索引很多时候可以覆盖索引，节省存储空间，避免回表，提高查询效率</p></li><li><p>要控制索引的数量，索引并不是多多益善，索引越多，维护索引结构的代价就越大，会影响增删改的效率</p></li><li><p>如果索引列不能存储NULL值，请在创建表时使用NOT NULL约束它。当优化器知道每列是否包含NULL值时，它可以更好地确定哪个索引最有效地用于查询</p></li></ol>`,122)]])}var h=r(p,[[`render`,m]]);export{f as __pageData,h as default};